15:     late CurrencyRepository repository;
16: 
17:     setUp(() {
18:       repository = CurrencyRepositoryImpl(mockRestDatasource, mockDbDatasource);
19:     });
20: 
21:     test('should return correct currency list when getCurrencyList is called', () async {
22:       final currencyList = [
23:         CurrencyModel(
24:           id: '1',
25:           nominal: 1,
26:           name: 'Доллар США',
27:           symbol: 'USD',
28:           value: 78.4181,
29:           previousValue: 78.5,
30:         ),
31:         CurrencyModel(
32:           id: '2',
33:           nominal: 1,
34:           name: 'Евро',
35:           symbol: 'EUR',
36:           value: 92.7440,
37:           previousValue: 92.2,
38:         ),
39:       ];
40: 
41:       when(mockRestDatasource.getCurrencyList()).thenAnswer((_) async => currencyList);
42: 
43:       final result = await repository.getCurrencyList();
44: 
45:       expect(result, currencyList);
46:       verify(mockRestDatasource.getCurrencyList()).called(1);
47:     });
48: 
49:     test('fetchRates returns requested page and hasMore flag', () async {
50:       final all = [
51:         for (int i = 0; i < 3; i++)
52:           CurrencyModel(id: '$i', nominal: 1, name: 'Валюта $i', symbol: 'C$i', value: i + 1.0, previousValue: i.toDouble()),
53:       ];
54:       when(mockRestDatasource.getCurrencyList()).thenAnswer((_) async => all);
55: 
56:       final page0 = await repository.fetchRates(const CurrencyPageRequest(base: 'USD', page: 0, pageSize: 2));
57: 
58:       expect(page0.items.map((c) => c.id), ['0', '1']);
59:       expect(page0.hasMore, isTrue);
60:     });
61: 
62:     test('fetchRates returns empty page beyond the end', () async {
63:       when(mockRestDatasource.getCurrencyList()).thenAnswer((_) async => const []);
64: 
65:       final page = await repository.fetchRates(const CurrencyPageRequest(base: 'USD', page: 5, pageSize: 20));
66: 
67:       expect(page.items, isEmpty);
68:       expect(page.hasMore, isFalse);
69:     });
70: 
71:     test('should complete successfully when saveCurrencyList is called', () async {
72:       final currencyList = [
73:         CurrencyModel(
74:           id: '1',
75:           nominal: 1,
76:           name: 'Юань',
77:           symbol: 'CNY',
78:           value: 10.9384,
79:           previousValue: 10.9112,
80:         ),
81:       ];
82: 
83:       await repository.saveCurrencyList(currencyList);
84: 
85:       verify(mockDbDatasource.saveCurrencyList(currencyList)).called(1);
86:     });
87:   });
