91: 
92:     setUp(() {
93:       repository = NewsRepositoryImpl(mockRestDatasource, mockDbDatasource);
94:     });
95: 
96:     test('should return news list when getNewsList is called', () async {
97:       final newsList = [
98:         for (int i = 0; i < 3; i++)
99:           NewsModel(title: 'Заголовок $i', link: 'https://example.com/$i', date: DateTime.now()),
100:       ];
101: 
102:       when(mockRestDatasource.getNewsList()).thenAnswer((_) async => newsList);
103: 
104:       final result = await repository.getNewsList();
105: 
106:       expect(result, newsList);
107:       verify(mockRestDatasource.getNewsList()).called(1);
108:     });
109: 
110:     test('loadNewsFeed with forceRefresh reads from network and caches', () async {
111:       final newsList = [
112:         NewsModel(title: 'Свежая новость', link: 'https://example.com/fresh', date: DateTime.now()),
113:       ];
114:       when(mockRestDatasource.getNewsList()).thenAnswer((_) async => newsList);
115: 
116:       final result = await repository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true));
117: 
