120:       verify(mockDbDatasource.saveNewsList(newsList)).called(1);
121:       verifyNever(mockDbDatasource.getNewsList());
122:     });
123: 
124:     test('loadNewsFeed without forceRefresh reads only from cache', () async {
125:       final cached = [
126:         NewsModel(title: 'Из кэша', link: 'https://example.com/cached', date: DateTime.now()),
127:       ];
128:       when(mockDbDatasource.getNewsList()).thenAnswer((_) async => cached);
129: 
