138:       final newsList = [
139:         NewsModel(title: 'Заголовок 1', link: 'https://example.com/1', date: DateTime.now()),
140:       ];
141: 
142:       await repository.saveNewsList(newsList);
143: 
144:       verify(mockDbDatasource.saveNewsList(newsList)).called(1);
145:     });
146:   });
