7: class SettingsRepositoryImpl implements SettingsRepository {
8:   SettingsRepositoryImpl(this._datasource);
9: 
10:   final PreferenceDatasource _datasource;
11: 
12:   final StreamController<bool> _authStatusController = StreamController.broadcast();
13:   final StreamController<AppThemeMode> _themeModeController = StreamController.broadcast();
14: 
15:   late bool _isAuth;
16: 
17:   @override
18:   Future<void> initAsyncData() async {
19:     final bool isAuth = await getToken() != null;
20:     _authStatusController.add(isAuth);
21:     _isAuth = isAuth;
22:   }
23: 
24:   @override
25:   Stream<bool> get isAuthStream => _authStatusController.stream;
26: 
27:   @override
28:   bool get isAuth => _isAuth;
29: 
30:   @override
31:   Stream<AppThemeMode> get themeModeStream => _themeModeController.stream;
32: 
33:   @override
34:   @Deprecated('v2: используйте readThemeMode(); будет удалено в v3')
35:   AppThemeMode get themeMode => readThemeMode();
36: 
37:   @override
38:   AppThemeMode readThemeMode() => _datasource.themeMode;
39: 
40:   @override
41:   void setThemeMode(AppThemeMode mode) {
42:     _datasource.setThemeMode(mode);
43: 
44:     _themeModeController.add(mode);
45:   }
46: 
47:   @override
48:   Future<String?> getToken() => _datasource.getToken();
49: 
50:   @override
51:   Future<void> setToken(String? token) async {
52:     await _datasource.setToken(token);
53: 
54:     _authStatusController.add(token != null);
55:   }
56: }

